<script>export let data;</script><section class="page"><div class="eyebrow">MY PAWCONNECT</div><h1>Hello, {data.user.name} 👋</h1><p class="sub">Your reports, listings and help requests in one place.</p><div class="dash-grid"><div class="stat"><span>Lost & Found</span><b>{data.reports.length}</b></div><div class="stat"><span>Adoption listings</span><b>{data.listings.length}</b></div><div class="stat"><span>Help requests</span><b>{data.requests.length}</b></div></div><div class="tabs"><a href="/lost-found/new">+ Report lost/found</a><a href="/help/new">+ Request help</a><a href="/adoption/new">+ List for adoption</a></div><h2>Your posts</h2>{#if data.reports.length}<div class="masonry">{#each data.reports as item}<a class="card" href={`/report/${item.id}`}><div class="card-body"><div class="meta"><span>{item.type}</span><span>{item.status}</span></div><h3>{item.title}</h3><p>{item.description}</p></div></a>{/each}</div>{/if}{#if data.listings.length}<h2 style="margin-top:40px">Your adoption listings</h2><div class="masonry">{#each data.listings as item}<a class="card" href={`/report/${item.id}?kind=adoption`}><div class="card-body"><div class="meta"><span>adoption</span><span>{item.status}</span></div><h3>{item.title}</h3><p>{item.description}</p></div></a>{/each}</div>{/if}{#if data.requests.length}<h2 style="margin-top:40px">Your help requests</h2><div class="masonry">{#each data.requests as item}<a class="card" href={`/report/${item.id}?kind=help`}><div class="card-body"><div class="meta"><span>help</span><span>{item.status}</span></div><h3>{item.title}</h3><p>{item.description}</p></div></a>{/each}</div>{/if}</section>
